<?php $C=community_detail_ui($locale); ?>
<section class="community-page"><div class="container community-account-page"><header><a href="<?=e(locale_url($locale,'community'))?>">← <?=e($C['brand'])?></a><h1><?=e($C['notifications'])?></h1><form method="post" action="<?=e(locale_url($locale,'community/notifications/read'))?>"><?=csrf_field()?><button class="btn btn-ghost"><?=e($C['mark_read'])?></button></form></header><div class="community-notification-list"><?php if(!$rows):?><div class="community-empty"><?=e($C['no_notifications'])?></div><?php else:foreach($rows as $n):?><a class="community-notification <?=$n['is_read']?'':'unread'?>" href="<?=e($n['link']?:locale_url($locale,'community'))?>"><span></span><div><strong><?=e($n['title'])?></strong><p><?=e($n['message'])?></p><small><?=e(time_ago((string)$n['created_at'],$locale))?></small></div></a><?php endforeach;endif;?></div></div></section>

